#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> K(n);
    vector<vector<pair<int,int>>> pieces(n);
    int totalCells = 0;

    for(int i = 0; i < n; i++){
        cin >> K[i];
        pieces[i].resize(K[i]);
        for(int j = 0; j < K[i]; j++){
            cin >> pieces[i][j].first >> pieces[i][j].second;
        }
        totalCells += K[i];
    }

    // For each piece, generate all distinct orientations, keeping original cell order
    // Each orientation: vector of (x,y) in original cell order, normalized to min=0
    auto getOrientations = [](const vector<pair<int,int>>& cells) -> vector<vector<pair<int,int>>> {
        set<vector<pair<int,int>>> seen;
        vector<vector<pair<int,int>>> res;
        for(int f = 0; f < 2; f++){
            for(int r = 0; r < 4; r++){
                vector<pair<int,int>> tr(cells.size());
                for(int i = 0; i < (int)cells.size(); i++){
                    int tx = cells[i].first, ty = cells[i].second;
                    if(f) tx = -tx;
                    for(int rr = 0; rr < r; rr++){
                        int nx = -ty, ny = tx;
                        tx = nx; ty = ny;
                    }
                    tr[i] = {tx, ty};
                }
                int minx=INT_MAX, miny=INT_MAX;
                for(auto [x,y]:tr){minx=min(minx,x);miny=min(miny,y);}
                for(auto &[x,y]:tr){x-=minx;y-=miny;}
                // Check uniqueness by sorted version
                auto sorted_tr = tr;
                sort(sorted_tr.begin(), sorted_tr.end());
                if(seen.insert(sorted_tr).second) res.push_back(tr);
            }
        }
        return res;
    };

    vector<vector<vector<pair<int,int>>>> orients(n);
    for(int i=0;i<n;i++) orients[i]=getOrientations(pieces[i]);

    vector<int> order(n);
    iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a,int b){return K[a]>K[b];});

    int sqA=(int)ceil(sqrt((double)totalCells));
    int W=max(sqA,1);
    for(int i=0;i<n;i++) for(auto&o:orients[i]) for(auto[x,y]:o) W=max(W,x+1);

    int Hmax=totalCells+200;
    vector<int> height(W+200,0);
    set<pair<int,int>> used;

    vector<vector<pair<int,int>>> result(n);

    for(int idx=0;idx<n;idx++){
        int i=order[idx];
        int bestScore=INT_MAX,bx=-1,by=-1,bo=-1;
        for(int oi=0;oi<(int)orients[i].size();oi++){
            auto&o=orients[i][oi];
            int ow=0,oh=0;
            for(auto[x,y]:o){ow=max(ow,x+1);oh=max(oh,y+1);}
            if(ow>W) continue;
            for(int x=0;x<=W-ow;x++){
                int miny=0;
                for(auto[cx,cy]:o) miny=max(miny,height[x+cx]-cy);
                bool ok=true;
                for(auto[cx,cy]:o) if(used.count({x+cx,miny+cy})){ok=false;break;}
                if(ok){
                    int sc=(long long)(miny+oh)*100000+x;
                    if(sc<bestScore){bestScore=sc;bx=x;by=miny;bo=oi;}
                }
            }
        }
        auto&o=orients[i][bo];
        result[i].resize(K[i]);
        for(int j=0;j<K[i];j++){
            int fx=bx+o[j].first, fy=by+o[j].second;
            result[i][j]={fx,fy};
            used.insert({fx,fy});
            height[fx]=max(height[fx],fy+1);
        }
    }

    int maxW=0,maxH=0;
    for(int i=0;i<n;i++) for(auto[x,y]:result[i]){maxW=max(maxW,x+1);maxH=max(maxH,y+1);}

    cout<<maxW<<" "<<maxH<<"\n";
    for(int i=0;i<n;i++){
        for(int j=0;j<K[i];j++){
            if(j) cout<<" ";
            cout<<result[i][j].first<<" "<<result[i][j].second;
        }
        cout<<"\n";
    }
}
